<?php
/** Project-owned read-only bridge. Never falls back to legacy simulated Composio data. */
class ComposioBridge {
    private $store,$http;
    const TOOLS=['SEARCH_CONSOLE_SEARCH_ANALYTICS_QUERY','GOOGLESEARCHCONSOLE_SEARCH_ANALYTICS_QUERY'];
    public function __construct($store,$http=null){$this->store=$store;$this->http=$http?:[AiHttp::class,'json'];}
    public function configure($project,$principal,$input){AiAccess::write();AiHub::need('gsc','use');$hub=new AiHub($this->store);$source=$hub->source($project,$input['source_id']??'');if($source['owner']!==$principal['owner']||!in_array('gsc',$source['kinds'],true))throw new RuntimeException('منبع سرچ کنسول متعلق به شما نیست.');$key=trim($input['api_key']??'');$account=trim($input['account_id']??'');$tool=$input['tool']??'';$site=trim($input['site']??'');if(strlen($key)<20||strlen($key)>400||preg_match('/[\r\n]/',$key)||!preg_match('/^[A-Za-z0-9_-]{3,150}$/D',$account)||!in_array($tool,self::TOOLS,true)||!preg_match('~^(https://[^\s]+|sc-domain:[A-Za-z0-9.-]+)$~D',$site))throw new RuntimeException('کلید، Connected Account، ابزار و Site دقیق لازم است.');$cfg=['key'=>$this->store->encrypt($key),'account'=>$account,'tool'=>$tool,'site'=>$site];$hub->configureAdapter($source,'composio',$cfg);}
    public function pull($source,$from,$to,$offset=0){return AiAccess::run($source['principal'],function($project)use($source,$from,$to,$offset){AiAccess::write();AiHub::need('gsc','use');$cfg=$source['composio']??[];if(!$source['enabled']||empty($cfg)||!in_array($cfg['tool']??'',self::TOOLS,true))throw new RuntimeException('اتصال Composio تنظیم نشده است.');foreach([$from,$to] as $d)if(!is_string($d)||!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$d)||!checkdate((int)substr($d,5,2),(int)substr($d,8,2),(int)substr($d,0,4)))throw new RuntimeException('تاریخ میلادی لازم است.');if($from>$to||strtotime($to)-strtotime($from)>93*86400||!is_int($offset)||$offset<0)throw new RuntimeException('بازهٔ دریافت معتبر نیست.');$body=['connected_account_id'=>$cfg['account'],'arguments'=>['siteUrl'=>$cfg['site'],'body'=>['startDate'=>$from,'endDate'=>$to,'dimensions'=>['date','page','query'],'rowLimit'=>1000,'startRow'=>$offset]]];$response=call_user_func($this->http,'https://backend.composio.dev/api/v3/tools/execute/'.rawurlencode($cfg['tool']),$body,['x-api-key: '.$this->store->decrypt($cfg['key'])]);$result=$response['body']??[];if(($response['status']??0)<200||$response['status']>=300||(($result['successful']??false)!==true&&($result['success']??false)!==true)||!empty($result['error']))throw new RuntimeException('Composio درخواست واقعی را تأیید نکرد؛ Tool slug، نسخه و دسترسی حساب را بررسی کنید.');$data=$result['data']??[];if(isset($data['data']))$data=$data['data'];if($data===[])$data=['rows'=>[]];if(!is_array($data)||!isset($data['rows'])||!is_array($data['rows']))throw new RuntimeException('ساختار خروجی Composio با قرارداد date/page/query تطبیق ندارد؛ هیچ داده‌ای ثبت نشد.');$rows=[];foreach($data['rows'] as $r){if(!is_array($r['keys']??null)||count($r['keys'])!==3)throw new RuntimeException('ابعاد خروجی سرچ کنسول باید date/page/query باشد.');$rows[]=['id'=>hash('sha256',json_encode($r['keys'])),'date'=>$r['keys'][0],'page'=>$r['keys'][1],'query'=>$r['keys'][2],'clicks'=>$r['clicks']??null,'impressions'=>$r['impressions']??null,'ctr'=>$r['ctr']??null,'position'=>$r['position']??null];}$out=(new AiHub($this->store))->ingest($project,$source,'gsc',$rows,'composio-'.bin2hex(random_bytes(16)),count($rows)<1000);$out['next_offset']=count($rows)===1000?$offset+1000:null;return $out;});}
    public function tick(){ $s=$this->store->read();$count=0;foreach($s['hub_sources']??[] as $source){if($count>=2)break;if(!$source['enabled']||empty($source['composio']))continue;$id=$source['id'];$progress=$s['composio_sync'][$id]??[];if(($progress['next_at']??0)>time())continue;$from=$progress['from']??gmdate('Y-m-d',time()-7*86400);$to=$progress['to']??gmdate('Y-m-d',time()-86400);try{$result=$this->pull($source,$from,$to,(int)($progress['offset']??0));$next=$result['next_offset']===null?['next_at'=>time()+86400,'last_success'=>time()]:['from'=>$from,'to'=>$to,'offset'=>$result['next_offset'],'next_at'=>time()+60];}catch(Throwable $e){$next=$progress+['from'=>$from,'to'=>$to,'offset'=>0];$next['next_at']=time()+3600;$next['last_error']=$e instanceof RuntimeException?$e->getMessage():'Composio sync failed';}$this->store->transaction(static function(&$s)use($id,$next,$source){if(($s['hub_sources'][$id]['revision']??null)===($source['revision']??null)&&!empty($s['hub_sources'][$id]['enabled']))$s['composio_sync'][$id]=$next;});$count++;}return $count;}

}
